/// behaviour.rs every_rejection_lists_at_least_one_failed_check: schema change that is not consistent.
#[test]
fn apply_change_example_7() {
    let schema: types::TenantSchema = fixture_fx_tenant_schema_6();
    let change: types::SchemaChange = types::SchemaChange::RemoveField {
        object: types::ObjectTypeId("note".to_string()),
        field: types::FieldId("nothing".to_string()),
    };
    assert_eq!(
        apply_change(&schema, &change),
        Err(Failure::Error(types::SchemaProblem::Problem(
            "no field note.nothing".to_string()
        )))
    );
}

