/// Example 9 of `apply-change`.
#[test]
fn apply_change_example_9() {
    let schema: types::TenantSchema = fixture_fx_tenant_schema_6();
    let change: types::SchemaChange = types::SchemaChange::DefineRole(types::RoleDef {
        id: types::RoleId("public".to_string()),
        label: "All".to_string(),
    });
    assert_eq!(
        apply_change(&schema, &change),
        Err(Failure::Error(types::SchemaProblem::Problem(
            "public is built in".to_string()
        )))
    );
}

