/// Removing a view that is not there is a problem.
#[test]
fn apply_change_example_22() {
    let schema: types::TenantSchema = fixture_fx_tenant_schema_6();
    let change: types::SchemaChange =
        types::SchemaChange::RemoveView(types::ViewId("nope".to_string()));
    assert_eq!(
        apply_change(&schema, &change),
        Err(Failure::Error(types::SchemaProblem::Problem(
            "no view nope".to_string()
        )))
    );
}

