/// A relationship on an unknown object is a problem.
#[test]
fn apply_change_example_24() {
    let schema: types::TenantSchema = fixture_fx_tenant_schema_6();
    let change: types::SchemaChange = types::SchemaChange::DefineRelationship {
        object: types::ObjectTypeId("tag".to_string()),
        field: types::FieldId("editor".to_string()),
        label: "Editor".to_string(),
        target: types::ObjectTypeId("person".to_string()),
        on_delete: types::OnDelete::Restrict,
        required: false,
    };
    assert_eq!(
        apply_change(&schema, &change),
        Err(Failure::Error(types::SchemaProblem::Problem(
            "no object type tag".to_string()
        )))
    );
}

/// Removing a field of an unknown object is a problem.
#[test]
fn apply_change_example_25() {
    let schema: types::TenantSchema = fixture_fx_tenant_schema_6();
    let change: types::SchemaChange = types::SchemaChange::RemoveField {
        object: types::ObjectTypeId("tag".to_string()),
        field: types::FieldId("body".to_string()),
    };
    assert_eq!(
        apply_change(&schema, &change),
        Err(Failure::Error(types::SchemaProblem::Problem(
            "no object type tag".to_string()
        )))
    );
}

/// A constraint on an unknown object is a problem.
#[test]
fn apply_change_example_26() {
    let schema: types::TenantSchema = fixture_fx_tenant_schema_6();
    let change: types::SchemaChange = types::SchemaChange::DefineConstraint {
        object: types::ObjectTypeId("tag".to_string()),
        constraint: types::ConstraintDef {
            id: types::ConstraintId("title_length".to_string()),
            expr: types::Expr::Cmp(
                types::CmpOp::Le,
                Box::new(types::Expr::Len(Box::new(types::Expr::Var(
                    types::Scope::New,
                    "title".to_string(),
                )))),
                Box::new(types::Expr::Lit(types::Value::Int(24))),
            ),
            message: "A title has at most 24 characters".to_string(),
        },
    };
    assert_eq!(
        apply_change(&schema, &change),
        Err(Failure::Error(types::SchemaProblem::Problem(
            "no object type tag".to_string()
        )))
    );
}

