/// Removing a unique constraint that does not exist is refused.
#[test]
fn apply_change_example_38() {
    let schema: types::TenantSchema = fixture_fx_tenant_schema_10();
    let change: types::SchemaChange = types::SchemaChange::RemoveUnique {
        object: types::ObjectTypeId("note".to_string()),
        unique: types::ConstraintId("title_status".to_string()),
    };
    assert_eq!(
        apply_change(&schema, &change),
        Err(Failure::Error(types::SchemaProblem::Problem(
            "no unique constraint note.title_status".to_string()
        )))
    );
}

