/// A retention that is not declared is not cleared.
#[test]
fn apply_change_example_53() {
    let schema: types::TenantSchema = fixture_fx_tenant_schema_6();
    let change: types::SchemaChange = types::SchemaChange::ClearRetention {
        object: types::ObjectTypeId("note".to_string()),
    };
    assert_eq!(
        apply_change(&schema, &change),
        Err(Failure::Error(types::SchemaProblem::Problem(
            "note declares no retention".to_string()
        )))
    );
}

