/// behaviour.rs every_rejection_lists_at_least_one_failed_check: stale schema version.
#[test]
fn change_schema_example_4() {
    let d: types::Draft = fixture_fx_draft_14();
    let changes: Vec<types::SchemaChange> = vec![types::SchemaChange::RemoveField {
        object: types::ObjectTypeId("note".to_string()),
        field: types::FieldId("body".to_string()),
    }];
    let expected_version: Option<types::SchemaVersion> = Some(types::SchemaVersion(99));
    let existing: types::ExistingData = types::ExistingData::Reject;
    assert_eq!(
        change_schema(&d, &changes, &expected_version, &existing),
        Err(Failure::Error(types::Rejection::Rejected(
            types::DomainError {
                kind: types::ErrorKind::SchemaConflict,
                message: "schema is at version 2, expected 99".to_string(),
                evidence: vec![
                    types::Check {
                        rule: "policy:builtin_owner".to_string(),
                        passed: true,
                        detail: "Manage on Schema".to_string()
                    },
                    types::Check {
                        rule: "intent:schema_conflict".to_string(),
                        passed: false,
                        detail: "schema is at version 2, expected 99".to_string()
                    }
                ],
                missing: None
            }
        )))
    );
}

/// Example 5 of `change-schema`.
#[test]
fn change_schema_example_5() {
    let d: types::Draft = fixture_fx_draft_14();
    let changes: Vec<types::SchemaChange> = Vec::new();
    let expected_version: Option<types::SchemaVersion> = None;
    let existing: types::ExistingData = types::ExistingData::Reject;
    assert_eq!(
        change_schema(&d, &changes, &expected_version, &existing),
        Err(Failure::Error(types::Rejection::Rejected(
            types::DomainError {
                kind: types::ErrorKind::InvalidIntent,
                message: "no changes given".to_string(),
                evidence: vec![
                    types::Check {
                        rule: "policy:builtin_owner".to_string(),
                        passed: true,
                        detail: "Manage on Schema".to_string()
                    },
                    types::Check {
                        rule: "intent:invalid_intent".to_string(),
                        passed: false,
                        detail: "no changes given".to_string()
                    }
                ],
                missing: None
            }
        )))
    );
}

