/// A change of the type of a setting under overrides is refused as an invalid schema, with the evidence so far (SET-004).
#[test]
fn change_schema_example_11() {
    let d: types::Draft = fixture_fx_draft_16();
    let changes: Vec<types::SchemaChange> =
        vec![types::SchemaChange::DefineSetting(types::SettingDef {
            id: types::SettingId("theme".to_string()),
            label: "theme".to_string(),
            r#type: types::SettingType("bool".to_string()),
            default: types::Value::Bool(false),
            levels: std::collections::BTreeSet::from([
                types::SettingLevel::Tenant,
                types::SettingLevel::Team,
                types::SettingLevel::Person,
            ]),
            locked_by: None,
        })];
    let expected_version: Option<types::SchemaVersion> = None;
    let existing: types::ExistingData = types::ExistingData::Reject;
    assert_eq!(
        change_schema(& d, & changes, & expected_version, & existing),
        Err(Failure::Error(types::Rejection::Rejected(types::DomainError { kind :
        types::ErrorKind::InvalidSchema, message :
        "setting theme: the type changes from string to bool while overrides of it exist (SET-004)"
        .to_string(), evidence : vec![types::Check { rule : "policy:builtin_owner"
        .to_string(), passed : true, detail : "Manage on Schema".to_string() },
        types::Check { rule : "permission:capability:setting-define".to_string(), passed
        : true, detail : "holds setting-define".to_string() }, types::Check { rule :
        "intent:invalid_schema".to_string(), passed : false, detail :
        "setting theme: the type changes from string to bool while overrides of it exist (SET-004)"
        .to_string() }], missing : None })))
    );
}

