/// Example 1 of `need-order`.
#[test]
fn need_order_example_1() {
    let xs: Vec<types::Need> = vec![
        types::Need::AllOf(types::ObjectTypeId("person".to_string())),
        types::Need::ByField {
            object: types::ObjectTypeId("note".to_string()),
            field: types::FieldId("slug".to_string()),
            value: types::Value::Str("b".to_string()),
        },
        types::Need::Record {
            object: types::ObjectTypeId("person".to_string()),
            id: types::RecordId(2),
        },
        types::Need::ByField {
            object: types::ObjectTypeId("note".to_string()),
            field: types::FieldId("slug".to_string()),
            value: types::Value::Str("a".to_string()),
        },
        types::Need::Record {
            object: types::ObjectTypeId("note".to_string()),
            id: types::RecordId(10),
        },
        types::Need::Record {
            object: types::ObjectTypeId("note".to_string()),
            id: types::RecordId(9),
        },
        types::Need::AllOf(types::ObjectTypeId("note".to_string())),
        types::Need::Record {
            object: types::ObjectTypeId("person".to_string()),
            id: types::RecordId(2),
        },
        types::Need::ByField {
            object: types::ObjectTypeId("note".to_string()),
            field: types::FieldId("rank".to_string()),
            value: types::Value::Int(3),
        },
    ];
    let want_: Vec<types::Need> = vec![
        types::Need::Record {
            object: types::ObjectTypeId("note".to_string()),
            id: types::RecordId(9),
        },
        types::Need::Record {
            object: types::ObjectTypeId("note".to_string()),
            id: types::RecordId(10),
        },
        types::Need::Record {
            object: types::ObjectTypeId("person".to_string()),
            id: types::RecordId(2),
        },
        types::Need::ByField {
            object: types::ObjectTypeId("note".to_string()),
            field: types::FieldId("rank".to_string()),
            value: types::Value::Int(3),
        },
        types::Need::ByField {
            object: types::ObjectTypeId("note".to_string()),
            field: types::FieldId("slug".to_string()),
            value: types::Value::Str("a".to_string()),
        },
        types::Need::ByField {
            object: types::ObjectTypeId("note".to_string()),
            field: types::FieldId("slug".to_string()),
            value: types::Value::Str("b".to_string()),
        },
        types::Need::AllOf(types::ObjectTypeId("note".to_string())),
        types::Need::AllOf(types::ObjectTypeId("person".to_string())),
    ];
    assert_eq!(need_order(&xs), want_);
}

/// The ledger needs come after the records, once each, unit-used before pool-used and by name.
